{"code": "import pandas as pd, numpy as np
df = pd.read_csv('data.csv')
d = df[df.account_id=='S5Tfd67'].copy()
def p(x):
    m,dd,y=x.split('/'); return (int(y),int(m),int(dd))
d['k']=d.date.map(p)
an=(2025,10,16); base=[(2025,10,x) for x in range(9,16)]
for col in ['instance_family','application','cloud_service']:
    a = d[d.k==an].groupby(col).unblended_cost.sum()
    b = d[d.k.isin(base)].groupby(col).unblended_cost.sum()/7
    comp = pd.concat([a,b],axis=1).fillna(0); comp.columns=['anom','base']; comp['delta']=comp.anom-comp.base
    series = d.pivot_table(index='k', columns=col, values='unblended_cost', aggfunc='sum').fillna(0)
    z = {}
    for f in series.columns:
        s = series[f].copy()
        if an in s.index:
            v = s.loc[an]; s = s.drop(an)
        else:
            v = 0.0
        z[f] = (v-s.mean())/s.std(ddof=1) if s.std()>0 else 0.0
    comp['z']=pd.Series(z)
    print('===',col)
    print(comp.sort_values('delta').head(10).round(2))"}
